#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=7
umask 077
[[ -t 0 ]] || { printf 'Run this wizard in an interactive terminal.\n' >&2; exit 1; }
cd "$(dirname "${BASH_SOURCE[0]}")/.."
ENV_FILE="$PWD/.env"

require_confirmation() {
  confirm "$1" || { say "Stopped. Re-run the wizard when ready."; exit 1; }
}

# Restrict captured values to literal Compose env values, with no expansion.
capture() {
  local key="$1" prompt="$2" pattern="$3"
  while true; do
    ask "$key" "$prompt"
    [[ "${!key}" =~ $pattern ]] && break
    warn "Enter a nonempty value in the requested format."
  done
  write_env "$key" "${!key}"
}

banner "VPS gateway setup"
say "Run this in a checkout on your Linux VPS, beside existing Traefik and Tailscale."
say "Stages: prerequisites, settings, tailnet policy, DNS/TLS, optional token, deploy, checks."
say "Settings go to .env. No GitHub secrets are needed."
require_confirmation "Use this procedure on this VPS?"

stage "Check the existing VPS services"
[[ "$(uname -s)" == Linux ]] || { warn "This setup requires Linux."; exit 1; }
for tool in docker tailscale; do
  command -v "$tool" >/dev/null || { warn "Install $tool on the VPS first."; exit 1; }
done
docker compose version
docker info >/dev/null
tailscale status
[[ -S /var/run/tailscale/tailscaled.sock ]] || { warn "Expected the host tailscaled socket at /var/run/tailscale/tailscaled.sock."; exit 1; }
say "Traefik v3 must already serve public HTTPS and have a working DNS challenge resolver."
say "Keep public TCP 443 reachable. The gateway control port 8080 is tailnet-only."
require_confirmation "Traefik is ready and this is the intended VPS?"
[[ ! -L "$ENV_FILE" ]] || { warn "Refusing a symlink at .env."; exit 1; }
[[ ! -e "$ENV_FILE" || -f "$ENV_FILE" ]] || exit 1
if [[ -f "$ENV_FILE" ]]; then
  backup=$(mktemp "$PWD/.env.backup.XXXXXX")
  cp -- "$ENV_FILE" "$backup"
  chmod 600 "$backup"
  say "Saved a private backup to $backup"
fi

stage "Save gateway settings"
say "Use the IPv4 address shown by tailscale ip -4:"
tailscale ip -4
capture GATEWAY_TAILSCALE_IP "Gateway Tailscale IPv4:" '^100\.[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}$'
actual_ip=$(tailscale ip -4)
[[ "$GATEWAY_TAILSCALE_IP" == "$actual_ip" ]] || { warn "The IP must match this VPS's Tailscale IPv4."; exit 1; }
say "Copy the public address from your VPS provider's server networking page."
capture GATEWAY_PUBLIC_IP "Public VPS IPv4 or IPv6:" '^[0-9a-fA-F:.]+$'
capture PUBLIC_DOMAIN "Public base domain, for example devrp.liuf.uk:" '^[a-z0-9]+([.-][a-z0-9]+)+$'
say "Read these values from your existing Traefik static config or Compose arguments."
say "Use the host directory mounted as Traefik's providers.file.directory, not its container path."
capture TRAEFIK_CONFIG_DIR "Absolute host path to the watched directory, without spaces:" '^/[-a-zA-Z0-9_./]+$'
[[ -d "$TRAEFIK_CONFIG_DIR" ]] || { warn "That watched directory does not exist."; exit 1; }
capture TRAEFIK_ENTRYPOINT "HTTPS entrypoint name, usually websecure:" '^[a-zA-Z0-9_-]+$'
capture TRAEFIK_RESOLVER "Existing DNS challenge resolver name, usually hetzner:" '^[a-zA-Z0-9_-]+$'
require_confirmation "These settings match the running Traefik deployment?"

stage "Authorize publication through Tailscale"
open_url "https://login.tailscale.com/admin/acls"
say "Merge the grants from docs/gateway-setup.md into your existing policy."
say "Replace example tags with selectors for your actual gateway and developer devices."
say "Do not replace the whole policy. Preserve your administrative access."
cat <<'POLICY'
  {"src":["tag:devrp-developer"],"dst":["tag:devrp-gateway"],
   "ip":["tcp:8080"],"app":{"devrp.liuf.uk/publish":[{}]}},
  {"src":["tag:devrp-gateway"],"dst":["tag:devrp-developer"],
   "ip":["tcp:20000-29999"]}
POLICY
say "The capability name stays devrp.liuf.uk/publish even with a different public domain."
say "Grants are additive. Remove broader access to developer forwarding ports, including allow-all rules."
say "Only the gateway should reach developer TCP ports 20000-29999."
say "On each developer machine, grant its local account Serve permission through tailscaled operator configuration."
require_confirmation "Policy saved, device selectors correct, and forwarding ports restricted?"

stage "Provision wildcard DNS and the shared certificate"
say "In your authoritative DNS provider, create a DNS-only record for *.$PUBLIC_DOMAIN."
say "Point it to $GATEWAY_PUBLIC_IP using A for IPv4 or AAAA for IPv6. Remove conflicting address records."
say "In Traefik, merge this into the existing default TLS store configuration."
say "If there is no existing store configuration, use a separate operator-owned file in $TRAEFIK_CONFIG_DIR."
cat <<TLS
 tls:
   stores:
     default:
       defaultGeneratedCert:
         resolver: $TRAEFIK_RESOLVER
         domain:
           main: $PUBLIC_DOMAIN
           sans:
             - '*.$PUBLIC_DOMAIN'
TLS
say "Do not create duplicate default stores or replace a certificate used by other services."
say "If the existing store serves other domains, extend its certificate SANs to include these names."
say "Keep forwardedHeaders.insecure and proxyProtocol.insecure false."
say "Trust only actual upstream proxies. For direct visitors leave trusted IP lists empty."
say "Do not set an entrypoint-wide resolver that infers certificates from ordinary devrp routes."
require_confirmation "DNS resolves to this VPS and Traefik has issued the shared certificate?"

stage "Optional wildcard publication credentials"
say "Ordinary names already use the shared wildcard. Nested names with devrp -w need Hetzner Cloud DNS."
if confirm "Enable wildcard publications with a Hetzner Cloud API token?"; then
  open_url "https://console.hetzner.com/"
  step "Select the project containing the DNS zone, then Security, API tokens, Generate API token."
  step "Create a Read & Write token and copy it now. It will not be displayed again."
  while true; do
    ask_secret HETZNER_TOKEN "Hetzner Cloud API token:"
    [[ "$HETZNER_TOKEN" =~ ^[a-zA-Z0-9_-]+$ ]] && break
    warn "Enter the token without whitespace."
  done
  write_env HETZNER_TOKEN "$HETZNER_TOKEN"
  step "Open the project's DNS zone and copy its zone name or ID."
  capture HETZNER_ZONE "Existing Cloud DNS zone name or ID:" '^[a-zA-Z0-9.-]+$'
else
  write_env HETZNER_TOKEN ""
  write_env HETZNER_ZONE ""
fi
chmod 600 "$ENV_FILE"
require_confirmation "Credential settings saved as intended?"

stage "Start the gateway"
say "Compose will build and start proxy-server using host networking and the existing tailscaled socket."
say "The gateway owns $TRAEFIK_CONFIG_DIR/devrp.yml and clears its routes on startup."
say "Stop any previous gateway instance first. Remove old devrp dynamic.yml routes if migrating."
say "The command below uses the saved .env values, even if this shell exports older settings."
# Compose gives shell variables precedence over --env-file. Clear only its inputs.
compose() (
  unset GATEWAY_TAILSCALE_IP GATEWAY_PUBLIC_IP PUBLIC_DOMAIN TRAEFIK_CONFIG_DIR
  unset TRAEFIK_ENTRYPOINT TRAEFIK_RESOLVER HETZNER_TOKEN HETZNER_ZONE
  docker compose --env-file "$ENV_FILE" -f "$PWD/docker-compose.yml" "$@"
)
compose config --quiet
require_confirmation "Build and start this gateway now?"
compose up -d --build proxy-server
compose ps
say "Inspect startup errors with: docker compose logs --tail=100 proxy-server"
require_confirmation "The gateway is running without startup errors?"

stage "Verify from a development machine"
say "Run on an authorized development machine with devrp installed:"
printf '    export SERVER=http://%s:8080\n' "$GATEWAY_TAILSCALE_IP"
say '    curl --fail "$SERVER/status"'
say '    devrp -i gateway-check -p 8000 -- python3 -m http.server --bind 127.0.0.1'
say "Wait for Ready, then open https://gateway-check.$PUBLIC_DOMAIN and check HTTPS."
say "Press Ctrl-C and confirm the route disappears. Use an available disposable name if occupied."
say "From an unauthorized tailnet device, confirm /status is denied or unreachable."
say "Confirm another device cannot connect to the development machine's forwarding listener."
say "Complete the remaining live acceptance checks in docs/gateway-setup.md, including -w if enabled."
if ! confirm "Have all live acceptance checks passed?"; then
  SKIPPED+=("Live acceptance checks in docs/gateway-setup.md. Deployment is not yet verified.")
fi
finish
say "Gateway configuration saved in $ENV_FILE. Keep this file and its backups private."
